package com.winlator.cmod.ai;

import java.io.ByteArrayOutputStream;
import java.io.File;
import java.io.IOException;
import java.io.InputStream;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.HashSet;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.Set;
import java.util.concurrent.TimeUnit;

/**
 * Runs a command generated by a language model. Treats it as hostile input.
 *
 * The model is asked to produce read-only diagnostics, but it will happily produce
 * {@code rm -rf /} if a user talks it into it, and a prompt-injected log file could push it there
 * too. So the decision is made here, not in the prompt: the string is tokenised, every pipeline
 * stage is checked against an allowlist of read-only binaries, every argument is checked for
 * write-capable flags, and only then is it exec'd directly with {@link ProcessBuilder} — no shell,
 * so metacharacters have no meaning even if they slip past the checks.
 */
public final class AiCommandRunner {

    /** Binaries that cannot modify the filesystem or the session state. */
    private static final Set<String> ALLOWED = new HashSet<>(Arrays.asList(
            "ls", "cat", "head", "tail", "grep", "egrep", "fgrep", "find", "file", "du", "df", "stat",
            "uname", "id", "ps", "which", "ldd", "strings", "md5sum", "sha1sum", "readelf", "wc",
            "sort", "uniq", "env", "date", "getprop", "free", "nproc", "echo", "basename", "dirname",
            "realpath", "readlink", "hexdump", "xxd", "od", "cut", "tr", "diff", "cmp", "zcat",
            "glxinfo", "vulkaninfo", "lspci", "nvidia-smi"
    ));

    /** Binaries allowed only with a restricted argument set. */
    private static final Set<String> CONDITIONAL = new HashSet<>(Arrays.asList(
            "dumpsys", "wine", "wineserver", "reg"
    ));

    /** Characters that only make sense to a shell; their presence signals a misunderstanding. */
    private static final String[] FORBIDDEN_SUBSTRINGS = {
            ";", "&&", "||", "`", "$(", "${", ">", "<", "\n", "\r", "\\0"
    };

    private static final int MAX_OUTPUT_BYTES = 160_000;

    public static final class Result {
        public final boolean ok;
        public final String command;
        public final String output;
        public final String rejection;

        private Result(boolean ok, String command, String output, String rejection) {
            this.ok = ok;
            this.command = command;
            this.output = output;
            this.rejection = rejection;
        }

        static Result rejected(String command, String reason) {
            return new Result(false, command, "", reason);
        }

        static Result success(String command, String output) {
            return new Result(true, command, output, null);
        }

        /** What gets handed back to the model as the tool result. */
        public String describe() {
            if (!ok) return "REJECTED: " + rejection;
            return output.isEmpty() ? "(no output)" : output;
        }
    }

    private final File workingDir;
    private final Map<String, String> environment;

    /**
     * @param workingDir  container root, so relative paths resolve where the user expects
     * @param environment the live session environment (from GuestProgramLauncherComponent), so
     *                    wine/ldd/glxinfo see the same libraries the game does
     */
    public AiCommandRunner(File workingDir, Map<String, String> environment) {
        this.workingDir = workingDir;
        this.environment = environment;
    }

    public Result run(String rawCommand, int timeoutSeconds) {
        if (rawCommand == null) return Result.rejected("", "Empty command.");
        String command = rawCommand.trim();
        if (command.isEmpty()) return Result.rejected("", "Empty command.");
        if (command.length() > 800) return Result.rejected(command, "Command is too long (limit 800 characters).");

        String violation = validate(command);
        if (violation != null) return Result.rejected(command, violation);

        int timeoutMs = Math.max(3, Math.min(timeoutSeconds <= 0 ? 20 : timeoutSeconds, 60)) * 1000;

        // Only the first pipeline stage is executed. Say so instead of silently pretending.
        String[] stages = command.split("\\|");
        String firstStage = stages[0].trim();
        try {
            String output = execute(firstStage, timeoutMs);
            if (stages.length > 1) {
                output += "\n[note] Pipes are not executed here; only the first stage ran. "
                        + "Call the tool again with the remaining stage if you still need it.";
            }
            return Result.success(command, output);
        }
        catch (Exception e) {
            return Result.rejected(command, "Execution failed: " + e.getMessage());
        }
    }

    /** @return null when acceptable, otherwise the reason it was rejected. */
    private String validate(String command) {
        for (String forbidden : FORBIDDEN_SUBSTRINGS) {
            if (command.contains(forbidden)) {
                return "The command contains '" + forbidden + "', which is not allowed. "
                        + "Only simple read-only commands and pipes between them are permitted.";
            }
        }

        for (String stage : command.split("\\|")) {
            String trimmed = stage.trim();
            if (trimmed.isEmpty()) return "Empty pipeline stage.";
            List<String> tokens = tokenize(trimmed);
            if (tokens.isEmpty()) return "Could not parse the command.";

            String binary = new File(tokens.get(0)).getName().toLowerCase(Locale.US);
            if (ALLOWED.contains(binary)) {
                String problem = checkArguments(binary, tokens);
                if (problem != null) return problem;
            }
            else if (CONDITIONAL.contains(binary)) {
                String problem = checkConditional(binary, tokens);
                if (problem != null) return problem;
            }
            else {
                return "'" + binary + "' is not on the read-only allowlist. Allowed: "
                        + String.join(", ", sortedAllowed()) + ".";
            }
        }
        return null;
    }

    private String checkArguments(String binary, List<String> tokens) {
        boolean isFind = binary.equals("find");
        for (int i = 1; i < tokens.size(); i++) {
            String token = tokens.get(i);

            // sed -i rewrites files in place. grep -i is harmless, so this is sed-specific.
            if (binary.equals("sed") && token.startsWith("-i")) {
                return "sed -i would modify files in place; only read-only sed is allowed.";
            }

            // find actions that write or execute.
            if (isFind && (token.equals("-delete") || token.equals("-exec") || token.equals("-execdir")
                    || token.equals("-ok") || token.equals("-okdir") || token.equals("-fprint")
                    || token.equals("-fprintf") || token.equals("-fls"))) {
                return "find action '" + token + "' can write or execute; not allowed.";
            }
        }
        return null;
    }

    private String checkConditional(String binary, List<String> tokens) {
        if (tokens.size() < 2) return "'" + binary + "' needs an argument.";

        String first = tokens.get(1).toLowerCase(Locale.US);

        if (binary.equals("dumpsys")) {
            if (first.equals("gpu") || first.equals("meminfo") || first.equals("surfaceflinger")) return null;
            return "dumpsys is limited to gpu, meminfo and SurfaceFlinger.";
        }

        if (binary.equals("wineserver")) {
            if (first.equals("-p") || first.equals("--version")) return null;
            return "wineserver is limited to -p and --version.";
        }

        if (binary.equals("wine")) {
            if (first.equals("--version") || first.equals("-version")) return null;
            if (first.equals("reg") && tokens.size() > 2 && tokens.get(2).equalsIgnoreCase("query")) return null;
            if (first.equals("cmd") && tokens.size() > 2 && tokens.get(2).equalsIgnoreCase("/c")) return null;
            return "wine is limited to --version, 'reg query' and 'cmd /c'. "
                    + "wineboot, winecfg and running installers would modify the prefix.";
        }

        if (binary.equals("reg")) {
            if (first.equals("query")) return null;
            return "reg is limited to 'reg query'.";
        }

        return null;
    }

    private List<String> sortedAllowed() {
        List<String> list = new ArrayList<>(ALLOWED);
        Collections.sort(list);
        return list;
    }

    /**
     * Splits a command into arguments, honouring double quotes and backslash-escaped spaces.
     * Unlike ProcessHelper.splitCommand this strips the quotes, which is what ProcessBuilder wants.
     */
    static List<String> tokenize(String command) {
        List<String> result = new ArrayList<>();
        StringBuilder current = new StringBuilder();
        boolean inQuotes = false;
        boolean hasToken = false;

        for (int i = 0; i < command.length(); i++) {
            char c = command.charAt(i);
            if (c == '"') {
                inQuotes = !inQuotes;
                hasToken = true;
            }
            else if (c == '\\' && i + 1 < command.length()
                    && (command.charAt(i + 1) == ' ' || command.charAt(i + 1) == '"')) {
                current.append(command.charAt(++i));
                hasToken = true;
            }
            else if ((c == ' ' || c == '\t') && !inQuotes) {
                if (hasToken || current.length() > 0) {
                    result.add(current.toString());
                    current.setLength(0);
                    hasToken = false;
                }
            }
            else {
                current.append(c);
                hasToken = true;
            }
        }
        if (hasToken || current.length() > 0) result.add(current.toString());
        return result;
    }

    /** Execs directly (no shell) and captures stdout+stderr up to a size cap. */
    private String execute(String command, int timeoutMs) throws IOException, InterruptedException {
        List<String> tokens = tokenize(command);
        if (tokens.isEmpty()) return "(no output)";

        ProcessBuilder builder = new ProcessBuilder(tokens);
        if (workingDir != null && workingDir.isDirectory()) builder.directory(workingDir);
        if (environment != null && !environment.isEmpty()) builder.environment().putAll(environment);

        Process process = builder.start();
        ByteArrayOutputStream buffer = new ByteArrayOutputStream();
        Thread reader = new Thread(() -> drain(process.getInputStream(), buffer), "ai-cmd-out");
        Thread errorReader = new Thread(() -> drain(process.getErrorStream(), buffer), "ai-cmd-err");
        reader.start();
        errorReader.start();

        boolean finished = process.waitFor(timeoutMs, TimeUnit.MILLISECONDS);
        if (!finished) {
            process.destroy();
            if (!process.waitFor(2, TimeUnit.SECONDS)) process.destroyForcibly();
            reader.join(500);
            errorReader.join(500);
            String partial = buffer.toString("UTF-8");
            return "Timed out after " + (timeoutMs / 1000) + "s; the process was killed."
                    + (partial.isEmpty() ? "" : "\nPartial output:\n" + truncate(partial));
        }

        reader.join(2000);
        errorReader.join(2000);
        return truncate(buffer.toString("UTF-8").trim());
    }

    private void drain(InputStream stream, ByteArrayOutputStream sink) {
        byte[] chunk = new byte[8192];
        int read;
        try {
            while ((read = stream.read(chunk)) != -1) {
                synchronized (sink) {
                    if (sink.size() < MAX_OUTPUT_BYTES) sink.write(chunk, 0, read);
                }
            }
        }
        catch (IOException ignored) {}
    }

    private String truncate(String text) {
        if (text.length() <= MAX_OUTPUT_BYTES) return text;
        return text.substring(0, MAX_OUTPUT_BYTES)
                + "\n... [output truncated at " + (MAX_OUTPUT_BYTES / 1000) + " KB]";
    }
}
